window.AUTH=window.AUTH||{};window.AUTH["19-1039"]={"d":"19-1039","id":"2020/19-1039","n":"PennEast Pipeline Co. v. New Jersey","briefs":[{"k":"petitioner","label":"Brief of petitioner PennEast Pipeline Company, LLC","date":"2021-03-01","url":"https://www.supremecourt.gov/DocketPDF/19/19-1039/170518/20210301153424973_19-1039%20PennEast%20Merits%20Brief%20FINAL.pdf","side":"pet","n":61},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2021-03-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-1039/171249/20210308193306999_19-1039tsacUnitedStates.pdf","side":"us","n":57},{"k":"respondent","label":"Brief of respondent New Jersey Conservation Foundation","date":"2021-03-31","url":"https://www.supremecourt.gov/DocketPDF/19/19-1039/173595/20210331160334869_19-1039%20NJCF%20A.pdf","side":"res","n":0},{"k":"respondent","label":"Brief of respondents New Jersey, et al.","date":"2021-03-31","url":"https://www.supremecourt.gov/DocketPDF/19/19-1039/173571/20210331153434849_19-1039%20RESPONDENTS%20BRIEF.pdf","side":"res","n":76},{"k":"reply","label":"Reply of petitioner PennEast Pipeline Company, LLC","date":"2021-04-16","url":"https://www.supremecourt.gov/DocketPDF/19/19-1039/175932/20210416130327619_19-1039%20PennEast%20Merits%20Reply%20Brief%20Final.pdf","side":"pet","n":24}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/594us2r62_19m1.pdf","tr":true,"items":[{"t":"case","label":"A.W. Duckett & Co. v. United States","cite":"266 U.S. 149","y":1924,"id":"scdb/1924-034","sc":1,"sum":"that claimant's leasehold interest being part of the res, was taken, and that a promise upon the part of the Government to pay for it was implied. P. 151. Omnia Commercial Co. v. United States, 261 U. S. 502, distinguished. 58 Ct. Clms. 234; id., 403, reversed. APPEAL from a judgment of the Court of Claims rejecting a claim for the value of a leasehold interest in property requisitioned during the late war. Mr. Don …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"op":9,"ar":4,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"0":"38","1":"25, 33","3":"passim","4":"12"}},{"t":"case","label":"Am. Energy Corp. v. Rockies Express Pipeline LLC","cite":"622 F.3d 602","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/622/602/","op":3,"by":{"0":"29","1":"14"}},{"t":"case","label":"Beekman v. Saratoga & Schenectady R.R. Co.","cite":"3 Paige Ch. 45","y":1831,"court":"N.Y. Ch.","url":"https://www.courtlistener.com/c/Paige%20Ch./3/45/","by":{"0":"8"}},{"t":"case","label":"Berman v. Parker","cite":"348 U.S. 26","y":1954,"id":"1940-1955/348us26","sc":1,"sum":"The Court found that the Fifth Amendment does not limit Congress' power to seize private property with just compensation to any specific purpose.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Blatchford v. Native Village of Noatak","cite":"501 U.S. 775","y":1991,"id":"1990/89-1782","sc":1,"op":8,"ar":5,"sum":"Respondents, Alaska Native villages, brought suit against petitioner, a state official, seeking an order requiring payment to them of money allegedly owed under a state revenue-sharing statute. The District Court dismissed the suit as violating the Eleventh Amendment. The Court of Appeals reversed, first on the ground that 28 U. S. C. § 1362 constituted a congressional abrogation of Eleventh Amendment immunity, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","1":"25, 31","3":"passim","4":"13"}},{"t":"case","label":"California v. Cent. Pac. R.R. Co.","cite":"127 U.S. 1","y":1888,"id":"scdb/1887-236","sc":1,"sum":"By the constitution of California two modes 'of assessment for taxation are prescribed: one, by a state board of equalization; the other, by county boards and local assessors. All property is directed to be assessed in the county, city, etc., in which it is situated, except that the franchise, roadway, road-bed, rails, and rolling-stock of any railroad operated in more than one county, are to be assessed by the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"California v. Deep Sea Rsch., Inc.","cite":"523 U.S. 491","y":1998,"id":"1997/96-1400","sc":1,"sum":"In a unanimous opinion the Court held that while precedent interpreting the Eleventh Amendment supports a limited bar on federal admiralty jurisdiction disputes centering on people or property that is in a state's possession, the same does not apply when the concerned state lacks possession of the disputed maritime property.","sumSrc":"Oyez","by":{"0":"42","3":"30","4":"12"}},{"t":"case","label":"Cent. Va. Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"op":6,"sum":"Holding that “those who crafted the Bankruptcy Clause” understood it to “operat[e] free and clear of the State's claim of sovereign immunity”.","sumSrc":"opinion","by":{"0":"41","3":"14, 29","4":"19"}},{"t":"case","label":"Cherokee Nation v. S. Kan. Ry. Co.","cite":"135 U.S. 641","y":1890,"id":"scdb/1889-250","sc":1,"op":8,"ar":2,"sum":"The act of Congress of July 4, 1884, 23 Stat. 73, c. 179, granting a right of way through the Indian Territory to the Southern Kansas Railway Company, for a railroad, telegraph and telephone line, is a valid exercise of the power of Congress to regulate commerce among the several States and with the Indian tribes.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"9, 10, 40","3":"16","4":"15"}},{"t":"case","label":"City of Tacoma v. Taxpayers","cite":"357 U.S. 320","y":1958,"id":"1957/509","sc":1,"op":2,"ar":3,"sum":"The judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45, 47","1":"9, 11, 12, 13, 14, 15","3":"42, 43"}},{"t":"case","label":"Edelman v. Jordan","cite":"415 U.S. 651","y":1974,"id":"1973/72-1410","sc":1,"sum":"The Eleventh Amendment of the Constitution bars that portion of the District Court's decree that ordered retroactive pavment of benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"FCC v. NextWave Pers. Commc’ns, Inc.","cite":"537 U.S. 293","y":2003,"id":"2002/01-653","sc":1,"sum":"The Court held that the FCC's cancellations of the licenses violated section 525(a) as revocations of government licenses solely for nonpayment of the debtors' dischargeable debts.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Fed. Mar. Comm’n v. S.C. State Ports Auth.","cite":"535 U.S. 743","y":2002,"id":"2001/01-46","sc":1,"op":3,"sum":"The Court held that state sovereign immunity bars the FMC from adjudicating a private party's complaint against a nonconsenting State. Historically, the Court noted, states were not subject to private suits in administrative adjudications when the Constitution was adopted, and states were thus presumptively immune from such actions.","sumSrc":"Oyez","by":{"0":"43","3":"passim","4":"22"}},{"t":"case","label":"Hans v. Louisiana","cite":"134 U.S. 1","y":1890,"id":"scdb/1889-145","sc":1,"op":2,"sum":"A State cannot, without its consent, be sued’in a Circuit Court of the United States by one of its own citizens, upon a suggestion that the case is one that arises under the Constitution and laws of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"33","3":"15"}},{"t":"case","label":"Head v. Amoskeag Mfg. Co.","cite":"113 U.S. 9","y":1885,"id":"scdb/1884-085","sc":1,"sum":"A statute of a State, authorizing any person to erect and maintain on Ms own land a water mill and mill-dam upon and across any stream not navigable, paying to the owners of lands flowed damages assessed in a judicial proceeding, does not deprive them of their property without due process of law, in violation of the Fourteenth Amendment of the Constitution of the 1 United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"7","1":"26"}},{"t":"case","label":"Jackson v. Metro. Edison Co.","cite":"419 U.S. 345","y":1974,"id":"1974/73-5845","sc":1,"sum":"The court affirmed the Third Circuit and held that Metropolitan Edison's termination of Jackson's service did not qualify as state action.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Kelo v. City of New London","cite":"545 U.S. 469","y":2005,"id":"2004/04-108","sc":1,"ar":1,"sum":"The Court held that the city's taking of private property to sell for private development qualified as a \"public use\" under the takings clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"7, 8","1":"26"}},{"t":"case","label":"Kohl v. United States","cite":"91 U.S. 367","y":1875,"id":"scdb/1875-135","sc":1,"op":13,"ar":5,"sum":"This was a proceeding instituted by the United States to appropriate a parcel of land in the city of Cincinnati as a site for a post-office and other, public uses.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"passim","1":"25, 28, 30","3":"18","4":"6, 11, 15, 16"}},{"t":"case","label":"Luxton v. N. River Bridge Co.","cite":"153 U.S. 525","y":1894,"id":"scdb/1893-251","sc":1,"op":6,"sum":"—Decided May 14, 1894.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"5, 9, 10, 37","1":"28, 32"}},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Miss. & Rum River Boom Co. v. Patterson","cite":"98 U.S. 403","y":1878,"id":"scdb/1878-111","sc":1,"op":1,"sum":"The plaintiff is a corporation created by the laws of Minnesota, known as the Mississippi and Rum River Boom Company, and the defendant is a citizen of the State of Illinois.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"4, 31","4":"12"}},{"t":"case","label":"Okla. ex rel. Phillips v. Guy F. Atkinson Co.","cite":"313 U.S. 508","y":1941,"id":"scdb/1940-065","sc":1,"op":6,"sum":"1. The Denison Dam and Reservoir Project on the Red River in Oklahoma and Texas, authorized by the Act of June 28, 1938, is a valid exercise of the commerce power by Congress. P. 516. This is a multi-purpose project-part of a comprehensive scheme for controlling floods in the Mississippi River through reservoir control of its tributaries, of which the Red River is one of the more important. It aims also to protect …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 28, 32","1":"25","3":"19","4":"8"}},{"t":"case","label":"Olcott v. Fond du Lac Cnty.","cite":"83 U.S. 678","y":1872,"id":"scdb/1872-138","sc":1,"sum":"This act authorized the people of the county to vote upon the question whether they would aid the building of the railroads named; and provided, in case the vote should be in favor of granting aid, that “ county orders ” should be issued as the.roads should be Completed. The sixth section of the act was thus:","sumSrc":"Headnote (U.S. Reports)","by":{"0":"8, 34"}},{"t":"case","label":"P.R. Aqueduct & Sewer Auth. v. Metcalf & Eddy, Inc.","cite":"506 U.S. 139","y":1993,"id":"1992/91-1010","sc":1,"sum":"States and state entities that claim to be \"arms of the State\" may take advantage of the collateral order doctrine of Cohen v. Beneficial Industrial Loan Corp., 337 U. S. 541, to appeal a district court order denying a claim of Eleventh Amendment immunity from suit in federal court. Although 28 U. S. C. § 1291 requires that appeals be taken from \"final decisions of the district courts,\" Cohen, supra, at 546, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47","3":"21"}},{"t":"case","label":"Parkes v. Nat. Gas Pipe Line Co.","cite":"249 P.2d 462","y":1952,"court":"Okla.","url":"https://www.courtlistener.com/c/P.2d/249/462/","by":{"0":"14"}},{"t":"case","label":"Permanent Mission of India to the United Nations v. City of New York","cite":"551 U.S. 193","y":2007,"id":"2006/06-134","sc":1,"ar":1,"sum":"The Court held 7-2 that the \"immovable property\" exception to sovereign immunity in the FSIA covers disputes over tax liens on the property as well as disputes over ownership and possession. The opinion by Justice Clarence Thomas ruled that a tax lien, by both its dictionary definition and its practical effect, is an interest or right in property.","sumSrc":"Oyez","by":{"0":"32","4":"9, 10"}},{"t":"case","label":"Schneidewind v. ANR Pipeline Co.","cite":"485 U.S. 293","y":1988,"id":"1987/86-986","sc":1,"sum":"The MPSC regulation of respondents through Act 144 impinges on a field that the federal regulatory scheme has occupied to the exclusion of state law, and Act 144 therefore is pre-empted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Shaffer v. Heitner","cite":"433 U.S. 186","y":1977,"id":"1976/75-1812","sc":1,"sum":"Appellee, a nonresident of Delaware, filed a shareholder's derivative suit in a Delaware Chancery Court, naming as defendants a corporation and its subsidiary, as well as 28 present or former corporate officers or directors, alleging that the individual defendants had violated their duties to the corporation by causing it and its subsidiary to engage in actions (which occurred in Oregon) that resulted in corporate …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","3":"27-28, 29"}},{"t":"case","label":"Stockton v. Baltimore & N.Y.R. Co.","cite":"32 F. 9","y":1887,"court":"C.C.D.N.J.","url":"https://www.courtlistener.com/c/F./32/9/","op":10,"ar":1,"by":{"0":"9, 32, 33","1":"29","3":"16","4":"15, 22"}},{"t":"case","label":"Tenn. Student Assistance Corp. v. Hood","cite":"541 U.S. 440","y":2004,"id":"2003/02-1606","sc":1,"sum":"Instead, the Court ruled that discharging a debt owed to a state in a bankruptcy procedure is different from a suit and therefore not barred by sovereign immunity. \"A bankruptcy court is able to provide the debtor a fresh start in this manner ... because the court's jurisdiction is premised on the debtor and his estate, and not on the creditors,\" wrote the Court.","sumSrc":"Oyez","by":{"0":"41, 42, 43","3":"29-30","4":"passim"}},{"t":"case","label":"Thatcher v. Tenn. Gas Transmission Co.","cite":"180 F.2d 644","y":1950,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/180/644/","by":{"0":"11, 14"}},{"t":"case","label":"United States v. 50 Acres of Land","cite":"469 U.S. 24","y":1984,"id":"1984/83-1170","sc":1,"sum":"The Fifth Amendment does not require that the United States pay a public condemnee compensation measured by the cost of acquiring a substitute facility that the condemnee has a duty to acquire, when the market value of the condemned property is ascertainable and when there is no showing of manifest injustice.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","3":"25, 26","4":"9"}},{"t":"case","label":"United States v. Carmack","cite":"329 U.S. 230","y":1946,"id":"scdb/1946-016","sc":1,"sum":"1. Under § 1 of the Condemnation Act of August 1, 1888, authorizing any officer of the Government authorized to procure real estate for the erection of a public building to acquire the same for the United States by condemnation \"whenever in his opinion it is necessary or advantageous to the Government to do so,\" and the Public Buildings Act of May 25, 1926, as amended, authorizing the Federal Works Administrator to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"25"}},{"t":"case","label":"United States v. Dow","cite":"357 U.S. 17","y":1958,"id":"1957/102","sc":1,"op":1,"sum":"The \"taking\" occurred in 1943 when the Government entered into physical possession of the land; the assignment of the claim for compensation was invalid under the Assignment of Claims Act; and the respondent was not entitled to receive the compensation award.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"United States v. Jones","cite":"109 U.S. 513","y":1883,"id":"scdb/1883-070","sc":1,"sum":"Conflict of Laws — Constitutional Law — Damages—JEminent Domain — State Courts.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Univ. of Tex. Sw. Med. Ctr. v. Nassar","cite":"570 U.S. 338","y":2013,"id":"2012/12-484","sc":1,"sum":"The Court found that Title VII of the Civil Rights Act of 1964 requires the plaintiff to prove their employer would not have taken an action but for the existence of improper motives.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Upper Skagit Indian Tribe v. Lundgren","cite":"138 S. Ct. 1649","y":2018,"id":"2017/17-387","sc":1,"ar":3,"sum":"The Court held that its prior decision in County of Yakima v. Confederated Tribes and Bands of Yakima Nation addressed only a question of statutory interpretation, not the question whether Indian tribes have sovereign immunity in rem lawsuits.","sumSrc":"Oyez","by":{"0":"32","3":"27, 28, 31","4":"9, 17"}},{"t":"case","label":"Williams v. Transcon. Gas Pipe Line Corp.","cite":"89 F. Supp. 485","y":1950,"court":"W.D.S.C.","url":"https://www.courtlistener.com/c/F.%20Supp./89/485/","by":{"0":"14"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"32, 34"}},{"t":"usc","label":"15 U.S.C. § 717","url":"https://www.law.cornell.edu/uscode/text/15/717","subs":["(a)"],"stext":{"head":"§717. Regulation of natural gas companies","paras":[[0,"(a) Necessity of regulation in public interest"],[0,"As disclosed in reports of the Federal Trade Commission made pursuant to S. Res. 83 (Seventieth Congress, first session) and other reports made pursuant to the authority of Congress, it is declared that the business of transporting and selling natural gas for ultimate distribution to the public is affected with a public interest, and that Federal regulation in matters relating to the transportation of natural gas and the sale thereof in interstate and foreign commerce is necessary in the public interest."],[0,"(b) Transactions to which provisions of chapter applicable"],[0,"The provisions of this chapter shall apply to the transportation of natural gas in interstate commerce, to the sale in interstate commerce of natural gas for resale for ultimate public consumption for domestic, commercial, industrial, or any other use, and to natural-gas companies engaged in such transportation or sale, and to the importation or exportation of natural gas in foreign commerce and to persons engaged in such importation or exportation, but shall not apply to any other transportation or sale of natural gas or to the local distribution of natural gas or to the facilities used for such distribution or to the production or gathering of natural gas."],[0,"(c) Intrastate transactions exempt from provisions of chapter; certification from State commission as conclusive evidence"],[0,"The provisions of this chapter shall not apply to any person engaged in or legally authorized to engage in the transportation in interstate commerce or the sale in interstate commerce for resale, of natural gas received by such person from another person within or at the boundary of a State if all the natural gas so received is ultimately consumed within such State, or to any facilities used by such person for such transportation or sale, provided that the rates and service of such person and facilities be subject to regulation by a State commission. The matters exempted from the provisions of this chapter by this subsection are declared to be matters primarily of local concern and subject to regulation by the several States. A certification from such State commission to the Federal Power Commission that such State commission has regulatory jurisdiction over rates and service of such person and facilities and is exercising such jurisdiction shall constitute conclusive evidence of such regulatory power or jurisdiction."],[0,"(d) Vehicular natural gas jurisdiction"],[0,"The provisions of this chapter shall not apply to any person solely by reason of, or with respect to, any sale or transportation of vehicular natural gas if such person is—"],[1,"(1) not otherwise a natural-gas company; or"],[1,"(2) subject primarily to regulation by a State commission, whether or not such State commission has, or is exercising, jurisdiction over the sale, sale for resale, or transportation of vehicular natural gas."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/717?type=usc&year=mostrecent&link-type=html"},"head":"§717. Regulation of natural gas companies","tname":"Commerce and Trade","by":{"0":"11","1":"1, 2, 2"}},{"t":"usc","label":"15 U.S.C. § 717f","url":"https://www.law.cornell.edu/uscode/text/15/717f","subs":["(c)","(e)","(h)","(c)(1)(A)","(d)","(e)(1)(B)"],"stext":{"head":"§717f. Construction, extension, or abandonment of facilities","paras":[[0,"(a) Extension or improvement of facilities on order of court; notice and hearing"],[0,"Whenever the Commission, after notice and opportunity for hearing, finds such action necessary or desirable in the public interest, it may by order direct a natural-gas company to extend or improve its transportation facilities, to establish physical connection of its transportation facilities with the facilities of, and sell natural gas to, any person or municipality engaged or legally authorized to engage in the local distribution of natural or artificial gas to the public, and for such purpose to extend its transportation facilities to communities immediately adjacent to such facilities or to territory served by such natural-gas company, if the Commission finds that no undue burden will be placed upon such natural-gas company thereby: Provided, That the Commission shall have no authority to compel the enlargement of transportation facilities for such purposes, or to compel such natural-gas company to establish physical connection or sell natural gas when to do so would impair its ability to render adequate service to its customers."],[0,"(b) Abandonment of facilities or services; approval of Commission"],[0,"No natural-gas company shall abandon all or any portion of its facilities subject to the jurisdiction of the Commission, or any service rendered by means of such facilities, without the permission and approval of the Commission first had and obtained, after due hearing, and a finding by the Commission that the available supply of natural gas is depleted to the extent that the continuance of service is unwarranted, or that the present or future public convenience or necessity permit such abandonment."],[0,"(c) Certificate of public convenience and necessity"],[0,"(1)(A) No natural-gas company or person which will be a natural-gas company upon completion of any proposed construction or extension shall engage in the transportation or sale of natural gas, subject to the jurisdiction of the Commission, or undertake the construction or extension of any facilities therefor, or acquire or operate any such facilities or extensions thereof, unless there is in force with respect to such natural-gas company a certificate of public convenience and necessity issued by the Commission authorizing such acts or operations: Provided, however, That if any such natural-gas company or predecessor in interest was bona fide engaged in transportation or sale of natural gas, subject to the jurisdiction of the Commission, on February 7, 1942, over the route or routes or within the area for which application is made and has so operated since that time, the Commission shall issue such certificate without requiring further proof that public convenience and necessity will be served by such operation, and without further proceedings, if application for such certificate is made to the Commission within ninety days after February 7, 1942. Pending the determination of any such application, the continuance of such operation shall be lawful."],[0,"(B) In all other cases the Commission shall set the matter for hearing and shall give such reasonable notice of the hearing thereon to all interested persons as in its judgment may be necessary under rules and regulations to be prescribed by the Commission; and the application shall be decided in accordance with the procedure provided in subsection (e) of this section and such certificate shall be issued or denied accordingly: Provided, however, That the Commission may issue a temporary certificate in cases of emergency, to assure maintenance of adequate service or to serve particular customers, without notice or hearing, pending the determination of an application for a certificate, and may by regulation exempt from the requirements of this section temporary acts or operations for which the issuance of a certificate will not be required in the public interest."],[0,"(2) The Commission may issue a certificate of public convenience and necessity to a natural-gas company for the transportation in interstate commerce of natural gas used by any person for one or more high-priority uses, as defined, by rule, by the Commission, in the case of—"],[1,"(A) natural gas sold by the producer to such person; and"],[1,"(B) natural gas produced by such person."],[0,"(d) Application for certificate of public convenience and necessity"],[0,"Application for certificates shall be made in writing to the Commission, be verified under oath, and shall be in such form, contain such information, and notice thereof shall be served upon such interested parties and in such manner as the Commission shall, by regulation, require."],[0,"(e) Granting of certificate of public convenience and necessity"],[0,"Except in the cases governed by the provisos contained in subsection (c)(1) of this section, a certificate shall be issued to any qualified applicant therefor, authorizing the whole or any part of the operation, sale, service, construction, extension, or acquisition covered by the application, if it is found that the applicant is able and willing properly to do the acts and to perform the service proposed and to conform to the provisions of this chapter and the requirements, rules, and regulations of the Commission thereunder, and that the proposed service, sale, operation, construction, extension, or acquisition, to the extent authorized by the certificate, is or will be required by the present or future public convenience and necessity; otherwise such application shall be denied. The Commission shall have the power to attach to the issuance of the certificate and to the exercise of the rights granted thereunder such reasonable terms and conditions as the public convenience and necessity may require."],[0,"(f) Determination of service area; jurisdiction of transportation to ultimate consumers"],[0,"(1) The Commission, after a hearing had upon its own motion or upon application, may determine the service area to which each authorization under this section is to be limited. Within such service area as determined by the Commission a natural-gas company may enlarge or extend its facilities for the purpose of supplying increased market demands in such service area without further authorization; and"],[0,"(2) If the Commission has determined a service area pursuant to this subsection, transportation to ultimate consumers in such service area by the holder of such service area determination, even if across State lines, shall be subject to the exclusive jurisdiction of the State commission in the State in which the gas is consumed. This section shall not apply to the transportation of natural gas to another natural gas company."],[0,"(g) Certificate of public convenience and necessity for service of area already being served"],[0,"Nothing contained in this section shall be construed as a limitation upon the power of the Commission to grant certificates of public convenience and necessity for service of an area already being served by another natural-gas company."],[0,"(h) Right of eminent domain for construction of pipelines, etc."],[0,"When any holder of a certificate of public convenience and necessity cannot acquire by contract, or is unable to agree with the owner of property to the compensation to be paid for, the necessary right-of-way to construct, operate, and maintain a pipe line or pipe lines for the transportation of natural gas, and the necessary land or other property, in addition to right-of-way, for the location of compressor stations, pressure apparatus, or other stations or equipment necessary to the proper operation of such pipe line or pipe lines, it may acquire the same by the exercise of the right of eminent domain in the district court of the United States for the district in which such property may be located, or in the State courts. The practice and procedure in any action or proceeding for that purpose in the district court of the United States shall conform as nearly as may be with the practice and procedure in similar action or proceeding in the courts of the State where the property is situated: Provided, That the United States district courts shall only have jurisdiction of cases when the amount claimed by the owner of the property to be condemned exceeds $3,000."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/717f?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§717f. Construction, extension, or abandonment of facilities","tname":"Commerce and Trade","by":{"0":"11, 1, 1, 11, 13, 38, passim","1":"2, 4, 2, 18, 2, 2, 3, 33, 3, passim","3":"4, passim"}},{"t":"usc","label":"15 U.S.C. § 717l","url":"https://www.law.cornell.edu/uscode/text/15/717l","by":{"0":"29"}},{"t":"usc","label":"15 U.S.C. § 717r","url":"https://www.law.cornell.edu/uscode/text/15/717r","subs":["(b)","(a)","(c)"],"stext":{"head":"§717r. Rehearing and review","paras":[[0,"(a) Application for rehearing; time"],[0,"Any person, State, municipality, or State commission aggrieved by an order issued by the Commission in a proceeding under this chapter to which such person, State, municipality, or State commission is a party may apply for a rehearing within thirty days after the issuance of such order. The application for rehearing shall set forth specifically the ground or grounds upon which such application is based. Upon such application the Commission shall have power to grant or deny rehearing or to abrogate or modify its order without further hearing. Unless the Commission acts upon the application for rehearing within thirty days after it is filed, such application may be deemed to have been denied. No proceeding to review any order of the Commission shall be brought by any person unless such person shall have made application to the Commission for a rehearing thereon. Until the record in a proceeding shall have been filed in a court of appeals, as provided in subsection (b), the Commission may at any time, upon reasonable notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any finding or order made or issued by it under the provisions of this chapter."],[0,"(b) Review of Commission order"],[0,"Any party to a proceeding under this chapter aggrieved by an order issued by the Commission in such proceeding may obtain a review of such order in the court of appeals of the United States for any circuit wherein the natural-gas company to which the order relates is located or has its principal place of business, or in the United States Court of Appeals for the District of Columbia, by filing in such court, within sixty days after the order of the Commission upon the application for rehearing, a written petition praying that the order of the Commission be modified or set aside in whole or in part. A copy of such petition shall forthwith be transmitted by the clerk of the court to any member of the Commission and thereupon the Commission shall file with the court the record upon which the order complained of was entered, as provided in section 2112 of title 28. Upon the filing of such petition such court shall have jurisdiction, which upon the filing of the record with it shall be exclusive, to affirm, modify, or set aside such order in whole or in part. No objection to the order of the Commission shall be considered by the court unless such objection shall have been urged before the Commission in the application for rehearing unless there is reasonable ground for failure so to do. The finding of the Commission as to the facts, if supported by substantial evidence, shall be conclusive. If any party shall apply to the court for leave to adduce additional evidence, and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for failure to adduce such evidence in the proceedings before the Commission, the court may order such additional evidence to be taken before the Commission and to be adduced upon the hearing in such manner and upon such terms and conditions as to the court may seem proper. The Commission may modify its findings as to the facts by reason of the additional evidence so taken, and it shall file with the court such modified or new findings, which is supported by substantial evidence, shall be conclusive, and its recommendation, if any, for the modification or setting aside of the original order. The judgment and decree of the court, affirming, modifying, or setting aside, in whole or in part, any such order of the Commission, shall be final, subject to review by the Supreme Court of the United States upon certiorari or certification as provided in section 1254 of title 28."],[0,"(c) Stay of Commission order"],[0,"The filing of an application for rehearing under subsection (a) shall not, unless specifically ordered by the Commission, operate as a stay of the Commission's order. The commencement of proceedings under subsection (b) of this section shall not, unless specifically ordered by the court, operate as a stay of the Commission's order."],[0,"(d) Judicial review"],[0,"(1) In general"],[1,"The United States Court of Appeals for the circuit in which a facility subject to section 717b of this title or section 717f of this title is proposed to be constructed, expanded, or operated shall have original and exclusive jurisdiction over any civil action for the review of an order or action of a Federal agency (other than the Commission) or State administrative agency acting pursuant to Federal law to issue, condition, or deny any permit, license, concurrence, or approval (hereinafter collectively referred to as \"permit\") required under Federal law, other than the Coastal Zone Management Act of 1972 (16 U.S.C. 1451 et seq.)."],[0,"(2) Agency delay"],[1,"The United States Court of Appeals for the District of Columbia shall have original and exclusive jurisdiction over any civil action for the review of an alleged failure to act by a Federal agency (other than the Commission) or State administrative agency acting pursuant to Federal law to issue, condition, or deny any permit required under Federal law, other than the Coastal Zone Management Act of 1972 (16 U.S.C. 1451 et seq.), for a facility subject to section 717b of this title or section 717f of this title. The failure of an agency to take action on a permit required under Federal law, other than the Coastal Zone Management Act of 1972, in accordance with the Commission schedule established pursuant to section 717n(c) of this title shall be considered inconsistent with Federal law for the purposes of paragraph (3)."],[0,"(3) Court action"],[1,"If the Court finds that such order or action is inconsistent with the Federal law governing such permit and would prevent the construction, expansion, or operation of the facility subject to section 717b of this title or section 717f of this title, the Court shall remand the proceeding to the agency to take appropriate action consistent with the order of the Court. If the Court remands the order or action to the Federal or State agency, the Court shall set a reasonable schedule and deadline for the agency to act on remand."],[0,"(4) Commission action"],[1,"For any action described in this subsection, the Commission shall file with the Court the consolidated record of such order or action to which the appeal hereunder relates."],[0,"(5) Expedited review"],[1,"The Court shall set any action brought under this subsection for expedited consideration."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/717r?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§717r. Rehearing and review","tname":"Commerce and Trade","by":{"0":"29, 44, 45","1":"4, passim, 18","3":"5, 12, 41, 42, 43"}},{"t":"usc","label":"16 U.S.C. § 791","url":"https://www.law.cornell.edu/uscode/text/16/791","by":{"0":"11"}},{"t":"usc","label":"16 U.S.C. § 814","url":"https://www.law.cornell.edu/uscode/text/16/814","stext":{"head":"§814. Exercise by licensee of power of eminent domain","paras":[[0,"When any licensee cannot acquire by contract or pledges an unimproved dam site or the right to use or damage the lands or property of others necessary to the construction, maintenance, or operation of any dam, reservoir, diversion structure, or the works appurtenant or accessory thereto, in conjunction with any improvement which in the judgment of the commission is desirable and justified in the public interest for the purpose of improving or developing a waterway or waterways for the use or benefit of interstate or foreign commerce, it may acquire the same by the exercise of the right of eminent domain in the district court of the United States for the district in which such land or other property may be located, or in the State courts. The practice and procedure in any action or proceeding for that purpose in the district court of the United States shall conform as nearly as may be with the practice and procedure in similar action or proceeding in the courts of the State where the property is situated: Provided, That United States district courts shall only have jurisdiction of cases when the amount claimed by the owner of the property to be condemned exceeds $3,000 1 Provided further, That no licensee may use the right of eminent domain under this section to acquire any lands or other property that, prior to October 24, 1992, were owned by a State or political subdivision thereof and were part of or included within any public park, recreation area or wildlife refuge established under State or local law. In the case of lands or other property that are owned by a State or political subdivision and are part of or included within a public park, recreation area or wildlife refuge established under State or local law on or after October 24, 1992, no licensee may use the right of eminent domain under this section to acquire such lands or property unless there has been a public hearing held in the affected community and a finding by the Commission, after due consideration of expressed public views and the recommendations of the State or political subdivision that owns the lands or property, that the license will not interfere or be inconsistent with the purposes for which such lands or property are owned."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/814?type=usc&year=mostrecent&link-type=html"},"head":"§814. Exercise by licensee of power of eminent domain","tname":"Conservation","by":{"0":"12, 15, 26, 27","1":"20, 29","3":"36"}},{"t":"usc","label":"16 U.S.C. § 824p","url":"https://www.law.cornell.edu/uscode/text/16/824p","subs":["(e)(1)"],"by":{"0":"10, 26"}},{"t":"usc","label":"16 U.S.C. § 825l","url":"https://www.law.cornell.edu/uscode/text/16/825l","stext":{"head":"§825l. Review of orders","paras":[[0,"(a) Application for rehearing; time periods; modification of order"],[0,"Any person, electric utility, State, municipality, or State commission aggrieved by an order issued by the Commission in a proceeding under this chapter to which such person, electric utility, State, municipality, or State commission is a party may apply for a rehearing within thirty days after the issuance of such order. The application for rehearing shall set forth specifically the ground or grounds upon which such application is based. Upon such application the Commission shall have power to grant or deny rehearing or to abrogate or modify its order without further hearing. Unless the Commission acts upon the application for rehearing within thirty days after it is filed, such application may be deemed to have been denied. No proceeding to review any order of the Commission shall be brought by any entity unless such entity shall have made application to the Commission for a rehearing thereon. Until the record in a proceeding shall have been filed in a court of appeals, as provided in subsection (b), the Commission may at any time, upon reasonable notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any finding or order made or issued by it under the provisions of this chapter."],[0,"(b) Judicial review"],[0,"Any party to a proceeding under this chapter aggrieved by an order issued by the Commission in such proceeding may obtain a review of such order in the United States court of appeals for any circuit wherein the licensee or public utility to which the order relates is located or has its principal place of business, or in the United States Court of Appeals for the District of Columbia, by filing in such court, within sixty days after the order of the Commission upon the application for rehearing, a written petition praying that the order of the Commission be modified or set aside in whole or in part. A copy of such petition shall forthwith be transmitted by the clerk of the court to any member of the Commission and thereupon the Commission shall file with the court the record upon which the order complained of was entered, as provided in section 2112 of title 28. Upon the filing of such petition such court shall have jurisdiction, which upon the filing of the record with it shall be exclusive, to affirm, modify, or set aside such order in whole or in part. No objection to the order of the Commission shall be considered by the court unless such objection shall have been urged before the Commission in the application for rehearing unless there is reasonable ground for failure so to do. The finding of the Commission as to the facts, if supported by substantial evidence, shall be conclusive. If any party shall apply to the court for leave to adduce additional evidence, and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for failure to adduce such evidence in the proceedings before the Commission, the court may order such additional evidence to be taken before the Commission and to be adduced upon the hearing in such manner and upon such terms and conditions as to the court may seem proper. The Commission may modify its findings as to the facts by reason of the additional evidence so taken, and it shall file with the court such modified or new findings which, if supported by substantial evidence, shall be conclusive, and its recommendation, if any, for the modification or setting aside of the original order. The judgment and decree of the court, affirming, modifying, or setting aside, in whole or in part, any such order of the Commission, shall be final, subject to review by the Supreme Court of the United States upon certiorari or certification as provided in section 1254 of title 28."],[0,"(c) Stay of Commission's order"],[0,"The filing of an application for rehearing under subsection (a) shall not, unless specifically ordered by the Commission, operate as a stay of the Commission's order. The commencement of proceedings under subsection (b) of this section shall not, unless specifically ordered by the court, operate as a stay of the Commission's order."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/825l?type=usc&year=mostrecent&link-type=html"},"head":"§825l. Review of orders","tname":"Conservation","by":{"0":"45","1":"9, 11, 12, 13, 14, 15","3":"42"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(a)"],"by":{"0":"47"}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","subs":["(a)(1)"],"by":{"0":"36"}},{"t":"usc","label":"49 U.S.C. § 24311","url":"https://www.law.cornell.edu/uscode/text/49/24311","subs":["(a)(1)(A)"],"stext":{"head":"§24311. Acquiring interests in property by eminent domain","paras":[[0,"(a) General Authority.—(1) To the extent financial resources are available, Amtrak may acquire by eminent domain under subsection (b) of this section interests in property—"],[1,"(A) necessary for intercity rail passenger transportation, except property of a rail carrier, a State, a political subdivision of a State, or a governmental authority; or"],[1,"(B) requested by the Secretary of Transportation in carrying out the Secretary's duty to design and build an intermodal transportation terminal at Union Station in the District of Columbia if the Secretary assures Amtrak that the Secretary will reimburse Amtrak."],[0,"(2) Amtrak may exercise the power of eminent domain only if it cannot—"],[1,"(A) acquire the interest in the property by contract; or"],[1,"(B) agree with the owner on the purchase price for the interest."],[0,"(b) Civil Actions.—(1) A civil action to acquire an interest in property by eminent domain under subsection (a) of this section must be brought in the district court of the United States for the judicial district in which the property is located or, if a single piece of property is located in more than one judicial district, in any judicial district in which any piece of the property is located. An interest is condemned and taken by Amtrak for its use when a declaration of taking is filed under this subsection and an amount of money estimated in the declaration to be just compensation for the interest is deposited in the court. The declaration may be filed with the complaint in the action or at any time before judgment. The declaration must contain or be accompanied by—"],[1,"(A) a statement of the public use for which the interest is taken;"],[1,"(B) a description of the property sufficient to identify it;"],[1,"(C) a statement of the interest in the property taken;"],[1,"(D) a plan showing the interest taken; and"],[1,"(E) a statement of the amount of money Amtrak estimates is just compensation for the interest."],[0,"(2) When the declaration is filed and the deposit is made under paragraph (1) of this subsection, title to the property vests in Amtrak in fee simple absolute or in the lesser interest shown in the declaration, and the right to the money vests in the person entitled to the money. When the declaration is filed, the court may decide—"],[1,"(A) the time by which, and the terms under which, possession of the property is given to Amtrak; and"],[1,"(B) the disposition of outstanding charges related to the property."],[0,"(3) After a hearing, the court shall make a finding on the amount that is just compensation for the interest in the property and enter judgment awarding that amount and interest on it. The rate of interest is 6 percent a year and is computed on the amount of the award less the amount deposited in the court from the date of taking to the date of payment."],[0,"(4) On application of a party, the court may order immediate payment of any part of the amount deposited in the court for the compensation to be awarded. If the award is more than the amount received, the court shall enter judgment against Amtrak for the deficiency."],[0,"(c) Authority To Condemn Rail Carrier Property Interests.—(1) If Amtrak and a rail carrier cannot agree on a sale to Amtrak of an interest in property of a rail carrier necessary for intercity rail passenger transportation, Amtrak may apply to the Surface Transportation Board for an order establishing the need of Amtrak for the interest and requiring the carrier to convey the interest on reasonable terms, including just compensation. The need of Amtrak is deemed to be established, and the Board, after holding an expedited proceeding and not later than 120 days after receiving the application, shall order the interest conveyed unless the Board decides that—"],[1,"(A) conveyance would impair significantly the ability of the carrier to carry out its obligations as a common carrier; and"],[1,"(B) the obligations of Amtrak to provide modern, efficient, and economical rail passenger transportation can be met adequately by acquiring an interest in other property, either by sale or by exercising its right of eminent domain under subsection (a) of this section."],[0,"(2) If the amount of compensation is not determined by the date of the Board's order, the order shall require, as part of the compensation, interest at 6 percent a year from the date prescribed for the conveyance until the compensation is paid."],[0,"(3) Amtrak subsequently may reconvey to a third party an interest conveyed to Amtrak under this subsection or prior comparable provision of law if the Board decides that the reconveyance will carry out the purposes of this part, regardless of when the proceeding was brought (including a proceeding pending before a United States court on November 28, 1990)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/24311?type=usc&year=mostrecent&link-type=html"},"head":"§24311. Acquiring interests in property by eminent domain","tname":"Transportation","by":{"0":"10, 26","3":"36"}},{"t":"law","label":"Pub. L. No. 80-245","by":{"0":"12"}},{"t":"reg","label":"18 C.F.R. § 157.10","url":"https://www.ecfr.gov/current/title-18/section-157.10","by":{"0":"29"}},{"t":"reg","label":"18 C.F.R. § 157.21","url":"https://www.ecfr.gov/current/title-18/section-157.21","by":{"0":"29"}},{"t":"reg","label":"18 C.F.R. § 157.6","url":"https://www.ecfr.gov/current/title-18/section-157.6","by":{"0":"29"}},{"t":"reg","label":"80 Fed. Reg. 62,068","url":"https://www.govinfo.gov/link/fr/80/62068","by":{"0":"18"}},{"t":"case","label":"Order Granting Certiorari, PennEast Pipeline Co., LLC v. New Jersey","cite":"2021 WL 357257","y":2021,"court":"U.S. Feb. 3","by":{"0":"44"}},{"t":"case","label":"Adorers of the Blood of Christ v. FERC","cite":"897 F.3d 187","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/897/187/","sum":"Holding that Section 717r(b) “foreclosed judicial review” of landowners’ religious objections to use of their land for a pipeline except through the exclusive review provisions of the NGA.","sumSrc":"brief:1","by":{"1":"14"}},{"t":"case","label":"Allegheny Defense Project v. FERC","cite":"964 F.3d 1","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/964/1/","sum":"Noting that FERC’s Certificate orders “split the atom of finality. They are not final enough for aggrieved parties to seek relief in court, but they are final enough for private pipeline companies to go to court and take private property by eminent domain.”.","sumSrc":"brief:3","by":{"1":"19","3":"5, 24, 41"}},{"t":"case","label":"Best v. Humboldt Placer Mining Co.","cite":"371 U.S. 334","y":1963,"id":"1962/52","sc":1,"sum":"Justice William O. Douglas wrote for a unanimous court holding that the administrative proceedings were proper. Instituting the condemnation suit in District Court was an appropriate way to obtain possession and was not inconsistent with the administrative proceedings. The District Court was right to wait for the administrative determination.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Chesapeake & O. Canal Co. v. Union Bank","cite":"5 F. Cas. 570","y":1830,"court":"C.C.D.C.","url":"https://www.courtlistener.com/c/F.%20Cas./5/570/","by":{"1":"27"}},{"t":"case","label":"Chiafalo v. Washington","cite":"140 S. Ct. 2316","y":2020,"id":"2019/19-465","sc":1,"sum":"The Court held that the Constitution does not prohibit Washington's “faithless elector” law, which requires presidential electors to vote the way state law directs.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Department of Homeland Sec. v. MacLean","cite":"574 U.S. 383","y":2015,"id":"2014/13-894","sc":1,"sum":"The Court ruled that the Whistleblower Protection Act bars an agency from taking enforcement action against employees who intentionally disclose sensitive security information.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Department of Transp. v. Association of Am. R.Rs.","cite":"575 U.S. 43","y":2015,"id":"2014/13-1080","sc":1,"sum":"The Court held that for purposes of the validity of metrics and standards, Amtrak is a governmental entity.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Friends of the Earth, Inc. v. Laidlaw Envtl. Servs. (TOC), Inc.","cite":"528 U.S. 167","y":2000,"id":"1999/98-822","sc":1,"sum":"The Court held that a citizen suitor's claim for civil penalties need not be dismissed as moot when the defendant, after commencement of the litigation, has come into compliance with its NPDES permit. \"A defendant's voluntary cessation of allegedly unlawful conduct ordinarily does not suffice to moot a case,\" Justice Ginsburg wrote for the Court. \"Congress has found that civil penalties in the Clean Water Act cases do more than promote immediate compliance... they also deter future violations,\" concluded Justice Ginsburg.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Georgia v. City of Chattanooga","cite":"264 U.S. 472","y":1924,"id":"scdb/1923-112","sc":1,"sum":"1. Land acquired and held for railway purposes by one State within the borders of another with the latter's consent remains subject to the eminent domain of the State in which it lies and subject to be condemned by that State, or her authorized municipality, for a public street, in proceedings against the owner State, even though she has not consented to be sued.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"30, 31","3":"31","4":"10, 12"}},{"t":"case","label":"Lomax v. Ortiz-Marquez","cite":"140 S. Ct. 1721","y":2020,"id":"2019/18-8369","sc":1,"sum":"The Court held that a dismissal without prejudice for failure to state a claim counts as a strike under the Prison Litigation Reform Act, 28 U.S.C. § 1915(g), which bars inmates from filing or appealing a federal civil action without paying the associated fees if they have filed three or more cases or appeals that were dismissed because the lawsuits were frivolous or malicious or did not properly state a legal claim for relief.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20"}},{"t":"case","label":"Pennsylvania v. Union Gas Co.","cite":"491 U.S. 1","y":1989,"id":"1988/87-1241","sc":1,"op":2,"ar":2,"sum":"The judgment is affirmed, and the case is remanded. 832 F. 2d 1343, affirmed and remanded. JUSTICE BRENNAN delivered the opinion of the Court with respect to Parts I and II, concluding that CERCLA, as amended by SARA, clearly expresses an intent to hold States liable in damages in federal court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Scudder v. Trenton Delaware Falls Co.","cite":"1 N.J. Eq. 694","y":1832,"court":"N.J. Ch.","url":"https://www.courtlistener.com/c/N.J.%20Eq./1/694/","by":{"1":"27"}},{"t":"case","label":"Seminole Tribe of Fla. v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"op":7,"ar":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"1":"22","3":"19, 23, 32"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Thunder Basin Coal Co. v. Reich","cite":"510 U.S. 200","y":1994,"id":"1993/92-896","sc":1,"sum":"Petitioner mine operator's nonunion work force designated two employees of the United Mine Workers of America (UMWA) to serve as miners' representatives under 30 U. S. C. §813(f). Claiming that the designations compromised its rights under the National Labor Relations Act (NLRA), petitioner refused to post information about the representatives as required by a regulation issued by the Department of Labor's Mine …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Tuscarora Nation of Indians v. Power Auth.","cite":"79 S. Ct. 4","y":1958,"url":"https://www.courtlistener.com/c/S.%20Ct./79/4/","sc":1,"by":{"1":"18"}},{"t":"case","label":"Vermont Agency of Natural Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"op":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"1":"16","3":"passim","4":"13"}},{"t":"case","label":"Virginia Uranium, Inc. v. Warren","cite":"139 S. Ct. 1894","y":2019,"id":"2018/16-1275","sc":1,"op":2,"sum":"The Fourth Circuit’s judgment that the Atomic Energy Act does not preempt Virginia’s prohibition on uranium mining in the Commonwealth is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20"}},{"t":"case","label":"Williams Natural Gas Co. v. City of Oklahoma City","cite":"890 F.2d 255","y":1989,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/890/255/","by":{"1":"14"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"33","3":"11, 40"}},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"1":"passim","3":"passim"}},{"t":"law","label":"Pub. L. No. 89-774","url":"https://www.govinfo.gov/link/statute/80/1324","by":{"1":"22"}},{"t":"law","label":"Pub. L. No. 93-496","url":"https://www.govinfo.gov/link/statute/88/1528","by":{"1":"22"}},{"t":"law","label":"Pub. L. No. 109-58","url":"https://www.govinfo.gov/link/plaw/109/public/58","by":{"1":"22"}},{"t":"law","label":"Pub. L. No. 102-486","url":"https://www.govinfo.gov/link/statute/106/3009","by":{"1":"21"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","by":{"1":"16"}},{"t":"usc","label":"16 U.S.C. § 791a","url":"https://www.law.cornell.edu/uscode/text/16/791a","by":{"1":"20, 29"}},{"t":"reg","label":"7 C.F.R. pt. 1468","url":"https://www.ecfr.gov/current/title-7/part-1468","by":{"1":"24"}},{"t":"reg","label":"18 C.F.R. pt. 157","url":"https://www.ecfr.gov/current/title-18/part-157","by":{"1":"2"}},{"t":"case","label":"Allen v. Cooper","cite":"140 S. Ct. 994","y":2020,"id":"2019/18-877","sc":1,"sum":"The Court held that the Copyright Remedy Clarification Act was not a valid abrogation of state sovereign immunity to allow authors of original expression to sue states who infringe their federal copyrights.","sumSrc":"Oyez","by":{"3":"29, 30, 32, 42"}},{"t":"case","label":"Alexander v. Pendleton","cite":"12 U.S. 462","y":1814,"id":"scdb/1814-033","sc":1,"sum":"Equity jurisdiction. — Notice.—Adverse possession.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"20"}},{"t":"case","label":"Algonquin v. Lowe","cite":"954 N.E.2d 228","y":2011,"court":"Ill. App.","url":"https://www.courtlistener.com/c/N.E.2d/954/228/","by":{"3":"28"}},{"t":"case","label":"ASARCO v. FERC","cite":"777 F.2d 764","y":1985,"court":"CADC","url":"https://www.courtlistener.com/c/F.2d/777/764/","op":1,"by":{"3":"5, 40"}},{"t":"case","label":"Atascadero State Hospital v. Scanlon","cite":"473 U.S. 234","y":1985,"id":"1984/84-351","sc":1,"op":1,"sum":"Respondent's action is proscribed by the Eleventh Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"32, 33, 36"}},{"t":"case","label":"Bd. of Trustees of Univ. of Alabama v. Garrett","cite":"531 U.S. 356","y":2001,"id":"2000/99-1240","sc":1,"sum":"The Court held that suits in federal court by state employees to recover money damages by reason of the state's failure to comply with Title I of the ADA are barred by the Eleventh Amendment.","sumSrc":"Oyez","by":{"3":"32"}},{"t":"case","label":"Belknap v. Schild","cite":"161 U.S. 10","y":1896,"id":"scdb/1895-108","sc":1,"sum":"The United States have no right to use a patented invention without license of the patentee or making compensation to him.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"27"}},{"t":"case","label":"Bostock v. Clayton Cty.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"3":"37"}},{"t":"case","label":"Chisholm v. Georgia","cite":"2 U.S. 419","y":1793,"id":"1789-1850/2us419","sc":1,"op":4,"sum":"The Court ruled that the states were under the jurisdiction of the Supreme Court and the federal government.","sumSrc":"Oyez","by":{"3":"1, 13"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"sum":"(1) As the claims are governed by the maritime law and within the admiralty jurisdiction, trial by jury is not required by the Seventh Amendment. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"35, 43"}},{"t":"case","label":"Dellmuth v. Muth","cite":"491 U.S. 223","y":1989,"id":"1988/87-1855","sc":1,"sum":"Noting, “in this area of the law, evidence of congressional intent must be both unequivocal and textual,” leaving a reader with “perfect confidence”.","sumSrc":"brief:3","by":{"3":"passim"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"3":"39"}},{"t":"case","label":"Fitzpatrick v. Bitzer","cite":"427 U.S. 445","y":1976,"id":"1975/75-251","sc":1,"op":3,"sum":"Holding that state sovereign immunity is necessarily limited by the enforcement provision of the Fourteenth Amendment.","sumSrc":"opinion","by":{"3":"14"}},{"t":"case","label":"Fla. Dep’t of State v. Treasure Salvors","cite":"458 U.S. 670","y":1982,"id":"1981/80-1348","sc":1,"sum":"The Court first held that while a state enjoys limited immunity from federal process under the Eleventh Amendment, its officers do not. In the present case, the seizure warrant was filed against Florida's officers in the Archives.","sumSrc":"Oyez","by":{"3":"30"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"3":"42"}},{"t":"case","label":"iv Goodtitle v. Kibbe","cite":"50 U.S. 471","y":1850,"id":"scdb/1850-072","sc":1,"sum":"The decision of this court in Pollard v. Hagan, 3 Howard, 212, reexamined and affirmed.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"Idaho v. Coeur d’Alene Tribe of Idaho","cite":"521 U.S. 261","y":1997,"id":"1996/94-1474","sc":1,"sum":"Authored by Justice Anthony Kennedy, the Court ruled that the Coeur d'Alene Tribe's suit against the state officials may not proceed in federal court because States enjoy Eleventh Amendment immunity in suits filed by Indian tribes.","sumSrc":"Oyez","by":{"3":"20, 28","4":"18"}},{"t":"case","label":"Minnesota v. United States","cite":"305 U.S. 382","y":1939,"id":"scdb/1938-118","sc":1,"sum":"1. The United States is an indispensable party defendant in a condemnation proceeding brought by a State to acquire a right of way over lands which the United States owns in fee and holds in trust for Indian allottees.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"27"}},{"t":"case","label":"Missouri v. Fiske","cite":"290 U.S. 18","y":1933,"id":"scdb/1933-007","sc":1,"op":1,"sum":"1. A State may. waive, by appearing, its immunity as a sovereign from being sued by individuals.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"27"}},{"t":"case","label":"Nev. Dep’t of Human Resources v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"op":2,"sum":"The Court held that State employees may recover money damages in federal court in the event of the State's failure to comply with the FMLA's family-care provision.","sumSrc":"Oyez","by":{"3":"32"}},{"t":"case","label":"Nevada v. United States","cite":"463 U.S. 110","y":1983,"id":"1982/81-2245","sc":1,"op":2,"sum":"Res judicata prevents the United States and the Tribe from litigating the instant claim.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"28"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"465 U.S. 89","y":1984,"id":"1982/81-2101","sc":1,"sum":"The Eleventh Amendment prohibited the District Court from ordering state officials to conform their conduct to state law.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"32"}},{"t":"case","label":"Quern v. Jordan","cite":"440 U.S. 332","y":1979,"id":"1978/77-841","sc":1,"sum":"In Edelman v. Jordan, 415 U. S. 651, it was held that retroactive welfare benefits awarded by a Federal District Court to the plaintiff class, by reason of wrongful denial of benefits by Illinois officials prior to the entry of the court's order determining the wrongfulness of their actions, violated the Eleventh Amendment, and that in an action under 42 U. S. C. § 1983 \"a federal court's remedial power, consistent …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"34"}},{"t":"case","label":"v Raygor v. Regents of Univ. of Minnesota","cite":"534 U.S. 533","y":2002,"id":"2001/00-1514","sc":1,"sum":"The Court held that the Board of Regents of the University of Minnesota never consented to suit in federal court on Raygor and Goodrich's state law claims and that the federal supplemental jurisdiction statute does not toll the period of limitations for state law claims asserted against nonconsenting state defendants that are dismissed on Eleventh Amendment grounds.","sumSrc":"Oyez","by":{"3":"32"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"39"}},{"t":"case","label":"Smith v. Reeves","cite":"178 U.S. 436","y":1900,"id":"scdb/1899-076","sc":1,"sum":"Within the meaning of the constitutional provisions relating to actions instituted by private persons against a State, this suit, though in form against an officer of the State of California, is in fact against the State itself.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"22"}},{"t":"case","label":"Sossamon v. Texas","cite":"563 U.S. 277","y":2011,"id":"2010/08-1438","sc":1,"op":2,"sum":"The Court held that a person may not sue a state official in his individual capacity for damages under the Religious Land Use and Institutional Persons Act.","sumSrc":"Oyez","by":{"3":"32"}},{"t":"case","label":"Sullivan v. Finkelstein","cite":"496 U.S. 617","y":1990,"id":"1989/89-504","sc":1,"sum":"The Secretary may immediately appeal a district court order effectively invalidating regulations limiting the kinds of inquiries that must be made to determine entitlement to disability insurance benefits and remanding a claim to the Secretary for consideration without those restrictions. Pp. 623-631. …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"37"}},{"t":"case","label":"Transwestern Pipeline v. Kerr-McGee Corp.","cite":"492 F.2d 878","y":1973,"court":"CA10","url":"https://www.courtlistener.com/c/F.2d/492/878/","by":{"3":"38"}},{"t":"case","label":"United States v. 564.54 Acres of Land","cite":"441 U.S. 506","y":1979,"id":"1978/78-488","sc":1,"sum":"Allowing respondent the fair market value of its property, rather than the cost of substitute facilities, is consistent with the principles of fairness underlying the Just Compensation Clause of the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"25"}},{"t":"case","label":"vi United States v. Alabama","cite":"313 U.S. 274","y":1941,"id":"scdb/1940-143","sc":1,"op":4,"sum":"(1) That'the tax lien is not objectionable under the Federal Colstitution as applied to a purchaser who bought on or after the tax day and before the amount of the tax had been fixed by levy and assessment. P. 279. (2) The fact that the purchaser, in such circumstances, was the United States did not invalidate the lien. P. 281. (3) Such a lien can not be enforced against the United States without its consent.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"27"}},{"t":"case","label":"United States v. Nordic Vill. Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"36-37"}},{"t":"case","label":"United States v. Texas","cite":"143 U.S. 621","y":1892,"id":"scdb/1891-138","sc":1,"op":5,"sum":"Holding that Article 3, § 2, gives the Supreme Court jurisdiction over a suit brought by the United States against a State.","sumSrc":"opinion","by":{"3":"20"}},{"t":"case","label":"United States v. Wittek","cite":"337 U.S. 346","y":1948,"id":"scdb/1948-093","sc":1,"sum":"The District of Columbia Emergency Rent Act of December 2, 1941, 55 Stat. 788, as amended, is not applicable to the United States as landlord of Government-owned defense housing in the District of Columbia.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"34"}},{"t":"case","label":"United States v. X-Citement Video, Inc.","cite":"513 U.S. 64","y":1994,"id":"1994/93-723","sc":1,"sum":"The Court relied on an awkward grammatical construction as it held that the term \"knowingly\" applied to the entire passage of the law. Writing for the majority, Chief Justice William Rehnquist stated that other interpretations failed to make sense since Congress obviously did not envision people accidentally mailing underage pornographic materials.","sumSrc":"Oyez","by":{"3":"35"}},{"t":"case","label":"Va. Off. for Prot. & Advoc. v. Stewart","cite":"563 U.S. 247","y":2011,"id":"2010/09-529","sc":1,"op":1,"sum":"The Court held that a federal court may hear a lawsuit for prospective injunctive relief against state officials brought by another agency of the same state.","sumSrc":"Oyez","by":{"3":"28"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"3":"1, 14"}},{"t":"const","label":"Article I, Section 8","by":{"3":"21"}},{"t":"usc","label":"16 U.S.C. § 824a-4","url":"https://www.law.cornell.edu/uscode/text/16/824a-4","by":{"3":"44"}},{"t":"usc","label":"29 U.S.C. § 794","url":"https://www.law.cornell.edu/uscode/text/29/794","by":{"3":"32"}},{"t":"usc","label":"29 U.S.C. § 794a","url":"https://www.law.cornell.edu/uscode/text/29/794a","by":{"3":"32"}},{"t":"usc","label":"33 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/33/1341","by":{"3":"4"}},{"t":"usc","label":"33 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/33/1344","by":{"3":"4"}},{"t":"usc","label":"42 U.S.C. § 4651","url":"https://www.law.cornell.edu/uscode/text/42/4651","by":{"3":"23"}},{"t":"usc","label":"54 U.S.C. § 306108","url":"https://www.law.cornell.edu/uscode/text/54/306108","by":{"3":"4"}},{"t":"rule","label":"Fed. R. Civ. P. 71.1","url":"https://www.law.cornell.edu/rules/frcp/rule_71.1","subs":["(e)","(h)"],"by":{"3":"6, 28, 30","4":"17, 18"}},{"t":"law","label":"Pub. L. No. 96-294","url":"https://www.govinfo.gov/link/statute/94/611","by":{"3":"36"}},{"t":"case","label":"Bauman v. Ross","cite":"167 U.S. 548","y":1897,"id":"scdb/1896-217","sc":1,"sum":"Under the Fifth Amendment to the Constitution of the United States, which declares “nor shall private property be taken for public use without just compensation,” Congress may direct that, when part of a parcel of land is appropriated to the public use for a highway in the District of Columbia, the tribunal vested by law with the duty of assessing the compensation or damages due to the owner, whether for the value …","sumSrc":"Headnote (U.S. Reports)","by":{"4":"18"}},{"t":"case","label":"Block v. North Dakota ex rel. Bd. Of Univ. & Sch. Lands","cite":"461 U.S. 273","y":1983,"id":"1982/81-2337","sc":1,"sum":"North Dakota filed suit in Federal District Court against several federal officials to resolve a dispute as to ownership of certain portions of a riverbed within the State. The United States claims title to most of the disputed area on the basis of its status as a riparian landowner on a nonnavigable river, while the State asserts that the river was navigable when North Dakota was admitted to the Union in 1889 and …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"9"}},{"t":"case","label":"Cnty. of Yakima v. Confederated Tribes & Bands of Yakima Indian Nation","cite":"502 U.S. 251","y":1992,"id":"1991/90-408","sc":1,"sum":"The Indian General Allotment Act of 1887 permits Yakima County to impose an ad valorem tax on reservation land patented in fee pursuant to the Act and owned by reservation Indians or the Yakima Indian Nation itself, but does not allow the county to enforce its excise tax on sales of such land.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"17"}},{"t":"case","label":"Coyle v. Smith","cite":"221 U.S. 559","y":1911,"id":"1900-1940/221us559","sc":1,"sum":"This was congressional overreaching. States are on an equal footing to determine their own location for the seat of government.","sumSrc":"Oyez","by":{"4":"15"}},{"t":"case","label":"U.S. Forest Serv. v. Cowpasture River Pres. Ass’n","cite":"140 S. Ct. 1837","y":2020,"id":"2019/18-1584","sc":1,"sum":"The Court held that the U.S. Forest Service has the authority to grant rights-of-way under the Mineral Leasing Act through lands traversed by the Appalachian Trail within national forests.","sumSrc":"Oyez","by":{"4":"5"}}]};